.cu-textarea {
  min-inline-size: 0;
  min-block-size: 6rem;
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  color: var(--cu-color-fg-default);
  background: var(--cu-color-background-default);
  font: inherit;
  resize: block;
}

.cu-textarea:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
  outline-offset: 3px;
}

.cu-textarea[aria-invalid='true'] {
  border-color: var(--cu-color-palette-brand);
}

.cu-textarea:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

import { FieldPrimitive } from '@chameleon-ui/primitives'
import type { ComponentPropsWithoutRef } from 'react'
import './styles.css'

export interface TextareaProps
  extends Omit<ComponentPropsWithoutRef<'textarea'>, 'className' | 'onChange' | 'value'> {
  value: string
  onChange: (value: string) => void
  label: string
  disabled?: boolean
  invalid?: boolean
  errorMessage?: string
  className?: string
}

export function Textarea({
  value,
  onChange,
  label,
  disabled = false,
  invalid = false,
  errorMessage = 'Please review this value.',
  className,
  id,
  ...props
}: TextareaProps) {
  const classes = ['cu-textarea', className].filter(Boolean).join(' ')

  return (
    <FieldPrimitive.Root
      className="cu-field"
      data-ai-role="textarea" data-ai-intent="enter-long-text"
      data-ai-state={invalid ? 'invalid' : disabled ? 'disabled' : 'default'}
      disabled={disabled}
      id={id}
      invalid={invalid}
    >
      <FieldPrimitive.Label className="cu-field__label">{label}</FieldPrimitive.Label>
      <FieldPrimitive.Textarea
        {...props}
        className={classes}
        value={value}
        onChange={(event) => onChange(event.currentTarget.value)}
      />
      {invalid ? (
        <FieldPrimitive.ErrorText className="cu-field__error">{errorMessage}</FieldPrimitive.ErrorText>
      ) : null}
    </FieldPrimitive.Root>
  )
}
